function calc(r){let sub=0,tax=0;for(let l of r.lines){let amount=Math.round(Number(l.qty)*Number(l.rate)*100)/100;sub+=amount;tax+=Math.round(amount*Number(l.tax))/100}sub=Math.round(sub*100)/100;tax=Math.round(tax*100)/100;const cents=Math.round((sub+tax)*100),round=r.autoRound?((Math.round(cents/100)*100-cents)/100):Number(r.round||0);return{sub,tax,round,grand:Math.round((sub+tax+round)*100)/100}}
