function setupItemPicker(){
const input=$('#quickItem'),toggle=$('#quickItemToggle'),list=$('#quickItemOptions'),picker=$('.item-picker');
const close=()=>{list.hidden=true;toggle.setAttribute('aria-expanded','false')};
const show=(query='')=>{const items=db.items.filter(i=>i.status==='Active'&&[i.name,i.code].some(v=>String(v||'').toLowerCase().includes(query.trim().toLowerCase())));
list.innerHTML=items.length?items.map(i=>`<button type="button" class="item-picker-option" data-item-id="${esc(i.id)}"><strong>${esc(i.name)}</strong><small>${esc(i.code)}</small></button>`).join(''):'<p class="item-picker-empty">'+(db.items.some(i=>i.status==='Active')?'No matching items. Try another name or code.':'No active items. Add an item in Item Master first.')+'</p>';
list.hidden=false;toggle.setAttribute('aria-expanded','true');};
toggle.onclick=()=>{if(list.hidden)show();else close()};
input.oninput=()=>{delete input.dataset.itemId;show(input.value)};
input.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();if(list.hidden)show(input.value);list.querySelector('button')?.focus()}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close()}});
list.onclick=e=>{const button=e.target.closest('[data-item-id]');if(!button)return;const item=db.items.find(i=>i.id===button.dataset.itemId&&i.status==='Active');if(!item)return;input.value=item.code+' · '+item.name;input.dataset.itemId=item.id;close();$('#quickError').textContent='';$('#quickQty').focus()};
list.onkeydown=e=>{const options=[...list.querySelectorAll('button')],index=options.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();options[(index+(e.key==='ArrowDown'?1:-1)+options.length)%options.length]?.focus()}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();toggle.focus()}};
picker.onfocusout=e=>{if(!picker.contains(e.relatedTarget))close()};
}
function quickAddItem(){const query=$('#quickItem').value.trim().toLowerCase(),qty=Number($('#quickQty').value);$('#quickError').textContent='';if(!query){$('#quickError').textContent='Choose an item from the search results, or use Add item below for a manual entry.';$('#quickItem').focus();return;}const matches=db.items.filter(i=>i.status==='Active'&&($('#quickItem').dataset.itemId?i.id===$('#quickItem').dataset.itemId:[i.code,i.name,i.code+' · '+i.name].some(v=>String(v).toLowerCase()===query)));if(matches.length!==1){$('#quickError').textContent=matches.length?'Select the item with its code to avoid duplicate names.':'Item not found. Select an active item from Item Master.';return;}if(!Number.isFinite(qty)||qty<=0){$('#quickError').textContent='Enter a quantity greater than zero.';$('#quickQty').focus();return;}const i=matches[0];addLine({desc:i.name,details:'',hsn:i.hsn||'',unit:i.unit||'',qty,rate:i.sale||0,tax:i.tax||0});$('#quickItem').value='';delete $('#quickItem').dataset.itemId;$('#quickItemOptions').hidden=true;$('#quickItemToggle').setAttribute('aria-expanded','false');$('#quickQty').value='1';$('#quickItem').focus();}
function customerOptions(selected='',query=''){let q=query.trim().toLowerCase();return db.customers.filter(c=>(c.status==='Active'||c.id===selected)&&[c.name,c.code,c.phone].some(x=>String(x||'').toLowerCase().includes(q))).map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)} · ${esc(c.code)}${c.phone?' · '+esc(c.phone):''}</option>`).join('')}
function applyCustomer(id){let c=db.customers.find(c=>c.id===id);if(!c)return;for(let [field,key] of [['customer','name'],['address','address'],['gst','gst'],['phone','phone'],['email','email']])$('#f-'+field).value=c[key]||'';toast('Customer details filled')}
function addLine(l){
const el=document.createElement('div');el.className='invoiceLine sales-line';
el.innerHTML=`<span class="sales-line-number"></span><div class="sales-product"><input class="desc" placeholder="Item name *" aria-label="Item name" value="${esc(l.desc||'')}" required><textarea class="details" rows="1" maxlength="2000" placeholder="(Description)" aria-label="Item description">${esc(l.details||'')}</textarea></div><label class="sales-cell"><span>HSN</span><input class="hsn" value="${esc(l.hsn||'')}" aria-label="HSN"></label><label class="sales-cell"><span>Qty.</span><input class="qty" type="number" step="0.001" min="0.001" value="${esc(l.qty??1)}" required aria-label="Quantity"><select class="unit" aria-label="Quantity unit"><option value="">Unit</option>${unitNames(l.unit).map(u=>`<option value="${esc(u)}" ${u===l.unit?'selected':''}>${esc(u)}</option>`).join('')}</select></label><label class="sales-cell"><span>Rate ₹</span><input class="rate" type="number" step="0.01" min="0" value="${esc(l.rate??0)}" required aria-label="Rate"></label><label class="sales-cell"><span>GST %</span><input class="tax" type="number" step="0.01" min="0" max="100" value="${esc(l.tax??0)}" required aria-label="GST percent"></label><div class="sales-line-total"><small>Amount ₹</small><output class="lineAmount">0.00</output></div><button class="remove-line" type="button" aria-label="Remove item" title="Remove item">×</button>`;
el.querySelector('button').onclick=()=>{el.remove();updateTotal()};$('#lines').append(el);updateTotal();
}
function readLines(){return [...document.querySelectorAll('.invoiceLine')].map(el=>Object.fromEntries(['desc','details','hsn','qty','unit','rate','tax'].map(k=>[k,el.querySelector('.'+k).value.trim()])))}
function updateTotal(){if(!$('#liveTotal'))return;const lines=readLines(),c=calc({lines,autoRound:true});$('#f-round').value=c.round.toFixed(2);$('#f-words').value=amountInWords(c.grand);$('#liveTotal').textContent=`Subtotal ₹${money(c.sub)} · Tax ₹${money(c.tax)} · Total ₹${money(c.grand)}`;
if($('#salesSubtotal')){$('#salesSubtotal').textContent=money(c.sub);$('#salesTax').textContent=money(c.tax);$('#salesGrand').textContent='₹'+money(c.grand);$('#salesTaxLabel').textContent=$('#f-taxMode').value==='IGST'?'IGST':'CGST + SGST';$('#salesLineCount').textContent=lines.length+(lines.length===1?' item':' items')+' · Total qty: '+Number(lines.reduce((sum,l)=>sum+(Number(l.qty)||0),0).toFixed(3));document.querySelectorAll('.invoiceLine').forEach((el,i)=>{el.querySelector('.sales-line-number').textContent=String(i+1).padStart(2,'0');el.querySelector('.lineAmount').textContent=money(Math.round(Number(lines[i].qty)*Number(lines[i].rate)*100)/100);});}}
async function saveInvoice(printAfter=false){let r=Object.fromEntries(new FormData($('#form')));r.lines=readLines();r.autoRound=true;r.round=calc(r).round;if(!r.lines.length)return $('#error').textContent='Add at least one invoice item.';if(!r.customer.trim()||!r.number.trim())return $('#error').textContent='Customer and invoice number are required.';if(db.invoices.some(i=>i.id!==editId&&i.number.toLowerCase()===r.number.trim().toLowerCase()))return $('#error').textContent='Invoice number already exists.';r.number=r.number.trim();r.id=editId||crypto.randomUUID();const total=calc(r).grand;if(total<0)return $('#error').textContent='Invoice total cannot be negative.';r.words=amountInWords(total);if(!r.words)return $('#error').textContent='Enter a valid invoice amount within the supported numeric range.';const printWindow=printAfter?window.open('','_blank'):null;if(printWindow)printWindow.document.write('<p>Saving invoice…</p>');if(await persist({...db,invoices:editId?db.invoices.map(x=>x.id===editId?r:x):[...db.invoices,r]})){$('#modal').close();render();toast('Invoice saved');if(printAfter)printInvoice(r,printWindow)}else if(printWindow)printWindow.close()}
function printInvoice(r,existingWindow){let c=calc(r),w=existingWindow||window.open('','_blank');if(!w)return alert('Allow pop-ups to open the invoice print preview.');let logo=new URL('logo.png',location.href).href;w.document.open();w.document.write(`<!doctype html><html><head><title>${esc(r.number)} - RAM FABRICATION</title><style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{font:12px Arial;color:#23394c;margin:0 auto;max-width:800px;padding:20px}header{display:flex;justify-content:space-between;align-items:start}img{width:260px}h1{font-size:23px;margin:20px 0}p{line-height:1.6;margin:6px 0}.info,.bottom{display:flex;justify-content:space-between;gap:20px;margin:20px 0}.box{padding:14px;border:1px solid #d8dfe5;flex:1}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{border:1px solid #d8dfe5;padding:11px 8px;text-align:left}th{background:#19364e;color:white}td:last-child{text-align:right}tr{break-inside:avoid}thead{display:table-header-group}.sum{width:310px;margin-left:auto}.sum td{padding:8px}.grand{font-weight:bold;background:#e8eef2}.sign{text-align:right;min-width:200px}.words{max-width:350px}.item-description{min-width:150px;max-width:300px;overflow-wrap:anywhere;white-space:normal}.item-notes{font-size:11px;line-height:1.5;margin-top:5px;color:#526577}.actions{background:#f1f6f3;padding:14px;margin-bottom:20px;border-radius:8px}button{padding:10px 18px;cursor:pointer;background:#24745d;color:white;border:0;border-radius:6px}@media print{body{padding:0}.actions{display:none}.bottom,.sum{break-inside:avoid}*{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><div class="actions"><button onclick="window.print()">Print / Save as PDF</button><p>Select <b>Save as PDF</b> as your printer. Use A4 paper and disable browser headers and footers.</p></div><header><img src="${logo}" alt="RAM FABRICATION"><h1>TAX INVOICE</h1></header><div class="info"><p>Fabrication • Roofing • Grills • Steps & SS Works<br>Vivekanandha Street, Kovil Thottam,<br>Neelikonampalayam, Cbe-33.<br>Phone: 99431 99797 | 80758 44604</p><p><b>GSTIN: 33HHYPS9430J1ZC</b><br>State: Tamilnadu | Code: 33</p></div><div class="info"><div class="box"><b>BILL TO</b><p>${esc(r.customer)}${r.phone?'<br>Phone: '+esc(r.phone):''}${r.email?'<br>Email: '+esc(r.email):''}<br>${esc(r.address).replace(/\n/g,'<br>')}<br>GSTIN: ${esc(r.gst)||'—'}</p></div><div class="box"><p><b>Invoice No.:</b> ${esc(r.number)}<br><b>Date:</b> ${esc(r.date)}<br>Despatched by: ${esc(r.dispatch)}<br>L.R. No.: ${esc(r.lr)}</p></div></div><table><thead><tr><th>No.</th><th>Description</th><th>HSN</th><th>Qty.</th><th>Rate (Rs.)</th><th>GST %</th><th>Amount (Rs.)</th></tr></thead><tbody>${r.lines.map((l,i)=>`<tr><td>${i+1}</td><td class="item-description"><strong>${esc(l.desc)}</strong>${l.details?'<div class="item-notes">('+esc(l.details).replace(/\n/g,'<br>')+')</div>':''}</td><td>${esc(l.hsn)}</td><td>${esc(l.qty)}${l.unit?' '+esc(l.unit):''}</td><td>${money(l.rate)}</td><td>${esc(l.tax)}</td><td>${money(Math.round(Number(l.qty)*Number(l.rate)*100)/100)}</td></tr>`).join('')}</tbody></table><div class="info"><div class="words"><p><b>Amount in words</b></p><p>${esc(amountInWords(c.grand))}</p></div><table class="sum"><tr><td>Subtotal</td><td>${money(c.sub)}</td></tr>${r.taxMode==='IGST'?`<tr><td>IGST</td><td>${money(c.tax)}</td></tr>`:`<tr><td>CGST</td><td>${money(Math.floor(c.tax*100/2)/100)}</td></tr><tr><td>SGST</td><td>${money(c.tax-Math.floor(c.tax*100/2)/100)}</td></tr>`}<tr><td>Round off</td><td>${money(c.round)}</td></tr><tr class="grand"><td>Grand total</td><td>Rs. ${money(c.grand)}</td></tr></table></div><div class="bottom"><p><b>BANK DETAILS</b><br>Bank: IOB, Singanallur<br>Account No.: 184402000001521<br>IFSC: IOBA0001844<br><br>Receiver's Signature: __________________</p><div class="sign"><b>For RAM FABRICATION</b><p style="margin-top:65px">Authorised Signature</p></div></div></body></html>`);w.document.close()}
render();
